import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"频道","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/channels.md","filePath":"guide/misskey/channels.md","lastUpdated":1789295632000}'),r={name:"guide/misskey/channels.md"};function s(n,a,o,d,h,c){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="频道" tabindex="-1">频道 <a class="header-anchor" href="#频道" aria-label="Permalink to &quot;频道&quot;">​</a></h1><p>频道是围绕特定主题的公共讨论区，每个频道有独立的时间线。不感兴趣的主题可以不关注，时间线互不打扰。</p><h2 id="浏览频道" tabindex="-1">浏览频道 <a class="header-anchor" href="#浏览频道" aria-label="Permalink to &quot;浏览频道&quot;">​</a></h2><p>通过侧栏「频道」进入频道列表：</p><ul><li><strong>热门</strong>：当前活跃的频道。</li><li><strong>正在关注</strong>：你关注的频道。</li><li><strong>正在管理</strong>：你创建的频道。</li></ul><p>每个频道显示参与人数和帖子数。</p><h2 id="关注与发帖" tabindex="-1">关注与发帖 <a class="header-anchor" href="#关注与发帖" aria-label="Permalink to &quot;关注与发帖&quot;">​</a></h2><ul><li>点击频道页面的「关注」按钮后，频道新帖会出现在你的时间线中（频道来源会标注在帖子上）。</li><li>在频道内发帖：该帖只投递到频道，不会进入「首页」时间线（关注者仍可通过频道看到）。</li><li>发帖时也可以在发布表单中直接选择投稿到指定频道。</li><li>频道帖子默认允许转发到频道外和引用（频道管理者可关闭此设置）。</li></ul><h2 id="创建频道" tabindex="-1">创建频道 <a class="header-anchor" href="#创建频道" aria-label="Permalink to &quot;创建频道&quot;">​</a></h2><p>点击「创建频道」，填写频道名称、描述、横幅图后即可创建。你将成为频道管理者，可以编辑频道信息、管理频道帖子。</p><p>频道中的帖子也会出现在<a href="/guide/posts#发现">发现页</a>并标注来源频道。</p>',11)])])}const _=e(r,[["render",s]]);export{u as __pageData,_ as default};
